public with sharing class ContactTriggerHandler {

    /**
     * Before insert / before update: copy BillingCountry → MailingCountry
     * and (insert only) AccountSource → LeadSource.
     * Uses exactly 1 SOQL query regardless of batch size.
     */
    public static void handleBefore(List<Contact> newRecords, Map<Id, Contact> oldMap) {
        if (newRecords == null || newRecords.isEmpty()) return;

        // Gather distinct AccountIds (bulk-safe: one map lookup instead of per-record query)
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newRecords) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) return;

        // SOQL #1
        Map<Id, Account> acctMap = new Map<Id, Account>(
            [SELECT Id, BillingCountry, AccountSource
             FROM Account
             WHERE Id IN :accountIds]
        );

        Boolean isInsert = Trigger.isInsert;

        for (Contact c : newRecords) {
            if (c.AccountId == null) continue;

            Account a = acctMap.get(c.AccountId);
            if (a == null) continue;

            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }

            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    /**
     * After insert: if a contact carries a phone and its account has none,
     * the FIRST contact (in trigger order) for that account sets the account phone.
     * Uses exactly 1 SOQL query and 1 DML statement regardless of batch size.
     */
    public static void handleAfterInsert(List<Contact> newRecords) {
        if (newRecords == null || newRecords.isEmpty()) return;

        // Gather AccountIds for contacts that could potentially supply a phone
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newRecords) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) return;

        // SOQL #2 – fetch current phone values in one shot
        Map<Id, Account> acctMap = new Map<Id, Account>(
            [SELECT Id, Phone
             FROM Account
             WHERE Id IN :accountIds]
        );

        // Track accounts that already had a phone (from the query) so we skip them,
        // and accounts for which a phone was already assigned by an earlier contact
        // in this same transaction (replicates the original per-record query behaviour
        // where the first update "hides" the phone from subsequent queries).
        Set<Id> phoneAlreadyPresent = new Set<Id>();
        Set<Id> phoneAlreadyAssigned = new Set<Id>();
        List<Account> toUpdate = new List<Account>();

        for (Contact c : newRecords) {
            if (c.AccountId == null || String.isBlank(c.Phone)) continue;

            Account a = acctMap.get(c.AccountId);
            if (a == null) continue;

            // Account already had a phone before this transaction → do nothing
            if (String.isNotBlank(a.Phone)) {
                phoneAlreadyPresent.add(c.AccountId);
                continue;
            }

            // Account phone is blank, but a previous contact already filled it in
            // this same batch → first-contact-wins rule, skip
            if (phoneAlreadyAssigned.contains(c.AccountId)) {
                continue;
            }

            a.Phone = c.Phone;
            phoneAlreadyAssigned.add(c.AccountId);
            toUpdate.add(a);
        }

        // DML #1 – single bulk update for all accounts that need a phone
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
```

