```apex
public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    public AccountsSelector() {
        this.dataAccess = fflib_ISObjectSelector.DataAccess.USER_MODE;
    }

    public override Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public override List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };

        Schema.FieldSet creditReview = Schema.SObjectType.Account.fieldSets.getMap().get('Credit_Review');
        if (creditReview != null) {
            Map<String, Schema.SObjectField> fieldMap = Account.SObjectType.getDescribe().fields.getMap();
            for (Schema.FieldSetMember fsm : creditReview.getFields()) {
                Schema.SObjectField sosField = fieldMap.get(fsm.getFieldPath());
                if (sosField != null && !fields.contains(sosField)) {
                    fields.add(sosField);
                }
            }
        }

        return fields;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        ContactsSelector contactsSelector = new ContactsSelector();

        List<String> parentFields = new List<String>();
        for (Schema.SObjectField field : getSObjectFieldList()) {
            parentFields.add(field.getDescribe().getName());
        }

        List<String> childFields = new List<String>();
        for (Schema.SObjectField field : contactsSelector.getSObjectFieldList()) {
            childFields.add(field.getDescribe().getName());
        }

        String userMode = (this.dataAccess == fflib_ISObjectSelector.DataAccess.USER_MODE)
            ? ' WITH USER_MODE'
            : '';

        String query = 'SELECT ' + String.join(parentFields, ', ')
            + ', (SELECT ' + String.join(childFields, ', ')
            + ' FROM Contacts)'
            + ' FROM Account'
            + ' WHERE Id IN :accountIds'
            + userMode;

        return Database.query(query);
    }
}
```

