            opp.StageName = 'Closed Won';
            opp.CloseDate = Date.today();
            uow.registerDirty(opp);

            Deal_Won__e evt = new Deal_Won__e(
                Opportunity_Id__c = String.valueOf(opp.Id),
                Amount__c = opp.Amount
            );
            uow.registerEvent(evt);

            count++;
        }

        // Single commit: DML first, then events (only if DML succeeded).
        uow.commit();

        return count;
    }
}
