public class Application {

    /**
     * Custom Unit of Work that extends fflib_SObjectUnitOfWork to also
     * publish platform events AFTER the regular DML has been committed.
     * If the DML throws, the exception propagates and no events are published.
     */
    public class OpportunityUnitOfWork extends fflib_SObjectUnitOfWork {

        private List<PlatformEventBus.EventBusEvent> m_events =
            new List<PlatformEventBus.EventBusEvent>();

        public OpportunityUnitOfWork(List<SObjectType> sObjectTypes) {
            super(sObjectTypes);
        }

        public void registerEvent(PlatformEventBus.EventBusEvent evt) {
            m_events.add(evt);
        }

        public override void commit() {
            // 1. Execute all registered DML (inserts, updates, deletes).
            //    Any DML exception propagates – events are never published.
            super.commit();

            // 2. Only reached when DML committed successfully.
            if (!m_events.isEmpty()) {
                EventBus.publish(m_events);
            }
        }
    }

    /**
     * Factory that produces OpportunityUnitOfWork instances,
     * mirroring the role of fflib_Application.UnitOfWorkFactory
     * but returning our platform-event-aware subclass.
     */
    public class UnitOfWorkFactory {

        public OpportunityUnitOfWork newUnitOfWork() {
            return new OpportunityUnitOfWork(
                new List<SObjectType>{
                    Account.SObjectType,
                    Opportunity.SObjectType
                }
            );
        }
    }

    public static final UnitOfWorkFactory UnitOfWork = new UnitOfWorkFactory();

    public static final fflib_Application.SelectorFactory Selector =
        new fflib_Application.SelectorFactory(
            new Map<SObjectType, Type>{
                Opportunity.SObjectType => OpportunitiesSelector.class
            }
        );
}
